Platform.Load("Core","1.1.1");
function logToTelemetry(level, processName, payload, errorBlock) {
  try {
    Platform.Function.InsertData("System_Telemetry_Log", 
      ["Timestamp", "Level", "Process", "Payload", "ErrorDetails"], 
      [Now(), level, processName, Stringify(payload), Stringify(errorBlock)]
    );
  } catch (e) { /* Respaldarse de un Fail Crudo */ }
}

try {
  // Lógica vital aquí expuesta...
} catch(ex) {
  logToTelemetry("CRITICAL", "ProcessOrders", null, ex);
}

token-cache.code:
function getValidToken() {
  var cached = Lookup("Sys_Vault", "AccessToken", "App", "PrimaryApp");
  var exp = Lookup("Sys_Vault", "Exp", "App", "PrimaryApp");
  var skewTime = new Date().getTime() + 60000; // colchón de 60s 

  if (exp && exp > skewTime) {
    return cached;
  }

  // Se necesita nuevo token puro
  var resp = fetchNewTokenFromAPI();
  // Usa UpdateData sobre tu DE Sys_Vault aquí
  return resp.token;
}

